import{_ as a,o as e,c as o,a5 as p}from"./chunks/framework.Cooo9kuv.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"IM013-批量为图片添加外边框使得图片显得高端","日期":"2026-04-12T00:00:00.000Z","修改日期":"2026-04-12T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["图片批处理"],"标签":["图片添加外边框","图片边框工具","批量图片添加外边框","批量添加边框"]},"headers":[],"relativePath":"md/图片批处理/IM013-批量为图片添加外边框使得图片显得高端.md","filePath":"md/图片批处理/IM013-批量为图片添加外边框使得图片显得高端.md"}'),n={name:"md/图片批处理/IM013-批量为图片添加外边框使得图片显得高端.md"};function r(_,t,s,m,c,g){return e(),o("div",null,[...t[0]||(t[0]=[p('<p>批量为图片添加白边和外部框线，使图片显得更加高端大气</p><p>如下图所示，图片外添加白边，白边外添加了一个灰色边框</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250224171413174038845318204.png" alt=""></p><p>比如A文件夹下有b、c、d、f....等文件夹，每个文件夹下都有一定的突破，将程序放在A文件夹下，运行程序后会自行创建一个与b、c、d、f....等文件夹同名_添加外边框的文件夹将处理后的图片放在该文件夹内，如下图所示</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250224171650174038861079706.png" alt=""></p><h3 id="imagemagick安装方式" tabindex="-1">ImageMagick安装方式 <a class="header-anchor" href="#imagemagick安装方式" aria-label="Permalink to &quot;ImageMagick安装方式&quot;">​</a></h3><p>先在电脑D盘创建文件夹：ImageMagick  然后将其安装在这个文件夹内</p><p>如果电脑没有D盘则在C盘按照此方式创建文件夹安装</p><p>如果你是win32位操作系统则使用32位的程序（X86）安装，如果是64位操作系统则按照64位的程序（X64）安装</p><p><strong>ImageMagick下载：</strong></p><p>通过网盘分享的文件：ImageMagick安装（必须安装此工具）<br> 链接: <a href="https://pan.baidu.com/s/12cRu46eo0m0xOFZP_aLt2A?pwd=myti" target="_blank" rel="noreferrer">https://pan.baidu.com/s/12cRu46eo0m0xOFZP_aLt2A?pwd=myti</a> 提取码: myti</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1508.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1508.html</a></p>',13)])])}const l=a(n,[["render",r]]);export{d as __pageData,l as default};
